from collections import Counter

class Solution:
    def recoverArray(self, n: int, sums: list[int]) -> list[int]:
        sums.sort()
        ans = []
        for _ in range(n):
            d = sums[1] - sums[0]
            count = Counter(sums)
            s0, s1 = [], []
            for x in sums:
                if count[x] > 0:
                    s0.append(x)
                    s1.append(x + d)
                    count[x] -= 1
                    count[x + d] -= 1
            if 0 in s0:
                ans.append(d)
                sums = s0
            else:
                ans.append(-d)
                sums = s1
        return ans

class Solution {
public:
    vector<int> recoverArray(int n, vector<int>& sums) {
        sort(sums.begin(), sums.end());
        vector<int> ans;
        for (int step = 0; step < n; step++) {
            int d = sums[1] - sums[0];
            unordered_map<int, int> count;
            for (int x : sums) count[x]++;
            vector<int> s0, s1;
            bool zeroInS0 = false;
            for (int x : sums) {
                if (count[x] > 0) {
                    s0.push_back(x);
                    s1.push_back(x + d);
                    count[x]--;
                    count[x + d]--;
                    if (x == 0) zeroInS0 = true;
                }
            }
            if (zeroInS0) {
                ans.push_back(d);
                sums = s0;
            } else {
                ans.push_back(-d);
                sums = s1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        int[] ans = new int[n];
        List<Integer> curr = new ArrayList<>();
        for (int x : sums) curr.add(x);

        for (int step = 0; step < n; step++) {
            int d = curr.get(1) - curr.get(0);
            Map<Integer, Integer> count = new HashMap<>();
            for (int x : curr) count.put(x, count.getOrDefault(x, 0) + 1);

            List<Integer> s0 = new ArrayList<>(), s1 = new ArrayList<>();
            boolean zeroInS0 = false;
            for (int x : curr) {
                if (count.getOrDefault(x, 0) > 0) {
                    s0.add(x);
                    s1.add(x + d);
                    count.put(x, count.get(x) - 1);
                    count.put(x + d, count.get(x + d) - 1);
                    if (x == 0) zeroInS0 = true;
                }
            }
            if (zeroInS0) {
                ans[step] = d;
                curr = s0;
            } else {
                ans[step] = -d;
                curr = s1;
            }
        }
        return ans;
    }
}

var recoverArray = function(n, sums) {
  sums.sort((a, b) => a - b);
  const ans = [];
  let curr = sums;
  for (let step = 0; step < n; step++) {
    const d = curr[1] - curr[0];
    const count = new Map();
    for (const x of curr) count.set(x, (count.get(x) || 0) + 1);
    const s0 = [], s1 = [];
    let zeroInS0 = false;
    for (const x of curr) {
      if ((count.get(x) || 0) > 0) {
        s0.push(x);
        s1.push(x + d);
        count.set(x, count.get(x) - 1);
        count.set(x + d, count.get(x + d) - 1);
        if (x === 0) zeroInS0 = true;
      }
    }
    if (zeroInS0) {
      ans.push(d);
      curr = s0;
    } else {
      ans.push(-d);
      curr = s1;
    }
  }
  return ans;
};
